const RINGS_MAP = {
  "triad core": 3, "tetrad cross": 4, "pentagram web": 5,
  "hexagonal crown": 6, "septagram cage": 7, "octahedral lattice": 8
};
const DEPTH_MAP = {
  "shallow prism": 1, "stepped echo": 2, "nested filigree": 3,
  "dense lacework": 4, "fractal haze": 5, "infinite dust": 6
};
const MOTIF_MAP = {
  "cartesian lattice": 0, "radiating spokes": 1, "spiral phyllotaxis": 2,
  "rosette rings": 3, "concentric ripples": 4, "droplet swarm": 5
};
const WARP_MAP = {
  "gentle camber": 0.2, "convex swell": 0.5, "pinched vortex": 0.8,
  "black hole funnel": 1.2, "astigmatic shear": 1.5, "singularity rip": 2.0
};
const PALETTE_MAP = {
  "obsidian gold": ["#000000", "#3a2a0d", "#8c6c23", "#d4af37", "#fef1b5"],
  "sapphire refraction": ["#011126", "#042c59", "#0c57a6", "#3d8ee6", "#b5d8ff"],
  "emerald opal": ["#021c11", "#084027", "#137a4b", "#47c286", "#b8f7d8"],
  "amethyst flare": ["#160224", "#3e0b5e", "#7016a6", "#b342f5", "#ebc4ff"],
  "prismatic spectral": ["#111111", "#ff2a2a", "#ffaa00", "#00ffaa", "#2a2aff"],
  "hyper-violet void": ["#050014", "#1a0040", "#4800b3", "#8800ff", "#d980ff"]
};

function invertCircle(cx, cy, cr, ix, iy, ir, p) {
  let dx = cx - ix;
  let dy = cy - iy;
  let d2 = dx * dx + dy * dy;
  let denom = d2 - cr * cr;
  if (p.abs(denom) < 0.001) return null;
  let s = (ir * ir) / denom;
  return { x: ix + dx * s, y: iy + dy * s, r: p.abs(cr * s) };
}

function getRgba(hex, alpha) {
  let r = parseInt(hex.slice(1, 3), 16);
  let g = parseInt(hex.slice(3, 5), 16);
  let b = parseInt(hex.slice(5, 7), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

p.setup = function() {
  p.createCanvas(800, 800);
  p.pixelDensity(1);
};

p.draw = function() {
  const ringsStr = p.getSynthVar('generator_rings') || 'triad core';
  const depthStr = p.getSynthVar('inversion_depth') || 'shallow prism';
  const motifStr = p.getSynthVar('base_motif') || 'cartesian lattice';
  const warpStr = p.getSynthVar('gravitational_warp') || 'gentle camber';
  const paletteStr = p.getSynthVar('chromatic_banding') || 'obsidian gold';

  const numGens = RINGS_MAP[ringsStr];
  const maxDepth = DEPTH_MAP[depthStr];
  const motifType = MOTIF_MAP[motifStr];
  const warpForce = WARP_MAP[warpStr];
  const palette = PALETTE_MAP[paletteStr];

  let gens = [];
  let breath = 150 * p.sin(p.frameCount * 0.02) + 200; 
  for (let i = 0; i < numGens; i++) {
    let a = i * p.TWO_PI / numGens + p.frameCount * 0.005;
    gens.push({ x: p.cos(a) * breath, y: p.sin(a) * breath, r: 180 });
  }

  let baseCircles = [];
  if (motifType === 0) {
    for (let x = -200; x <= 200; x += 100) for (let y = -200; y <= 200; y += 100) baseCircles.push({ x, y, r: 40 });
  } else if (motifType === 1) {
    for (let i = 0; i < 8; i++) { let a = i * p.PI / 4; baseCircles.push({ x: p.cos(a) * 150, y: p.sin(a) * 150, r: 35 }); baseCircles.push({ x: p.cos(a) * 50, y: p.sin(a) * 50, r: 15 }); }
  } else if (motifType === 2) {
    for (let i = 1; i < 20; i++) { let a = i * 2.3999; let r = i * 12; baseCircles.push({ x: p.cos(a) * r, y: p.sin(a) * r, r: 10 + i }); }
  } else if (motifType === 3) {
    for (let i = 0; i < 12; i++) { let a = i * p.PI / 6; baseCircles.push({ x: p.cos(a) * 100, y: p.sin(a) * 100, r: 60 }); }
  } else if (motifType === 4) {
    for (let i = 1; i <= 4; i++) { baseCircles.push({ x: 0, y: 0, r: i * 60 }); }
  } else {
    for (let i = 0; i < 15; i++) {
      let a = i * 0.4 + p.frameCount * 0.03;
      let rad = 150 + 100 * p.sin(p.frameCount * 0.05 + i);
      baseCircles.push({ x: p.cos(a) * rad, y: p.sin(a) * rad, r: 18 + 12 * p.cos(i * 2) });
    }
  }

  let queue = baseCircles.map(c => ({ ...c, depth: 0 }));
  let all = [...queue];
  let head = 0;

  while (head < queue.length && all.length < 350) {
    let c = queue[head++];
    if (c.depth >= maxDepth) continue;
    for (let g of gens) {
      let inv = invertCircle(c.x, c.y, c.r, g.x, g.y, g.r, p);
      if (inv && inv.r > 1.5) {
        let d2 = inv.x * inv.x + inv.y * inv.y;
        if (d2 < 160000) { 
          inv.depth = c.depth + 1;
          queue.push(inv);
          all.push(inv);
        }
      }
    }
  }

  let layers = [];
  for (let i = 0; i <= maxDepth; i++) layers[i] = [];

  for (let c of all) {
    let d = p.dist(0, 0, c.x, c.y);
    let a = p.atan2(c.y, c.x);
    let nd = d / (1.0 + warpForce * p.exp(-d * d / 200000.0));
    a += warpForce * p.exp(-d / 300.0);

    let wr = c.r * (nd / (d + 0.001));
    if (wr > 0.5 && wr < 1000) {
      layers[c.depth].push({ x: p.cos(a) * nd, y: p.sin(a) * nd, r: wr });
    }
  }

  let ctx = p.drawingContext;
  p.background(palette[0]);

  p.push();
  p.translate(p.width / 2, p.height / 2);

  ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i <= maxDepth; i++) {
    if (!layers[i] || layers[i].length === 0) continue;

    ctx.strokeStyle = palette[(i + 1) % palette.length];
    ctx.fillStyle = getRgba(palette[(i + 2) % palette.length], 0.12);
    ctx.lineWidth = 2.5;

    ctx.beginPath();
    for (let c of layers[i]) {
      ctx.moveTo(c.x + c.r, c.y);
      ctx.arc(c.x, c.y, c.r, 0, p.TWO_PI);
    }
    ctx.fill();
    ctx.stroke();
  }

  ctx.globalCompositeOperation = 'source-over';
  let pupilRad = 35 + 10 * p.sin(p.frameCount * 0.04);

  ctx.strokeStyle = palette[1];
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(0, 0, pupilRad + 2, 0, p.TWO_PI);
  ctx.stroke();

  ctx.fillStyle = palette[0];
  ctx.beginPath();
  ctx.arc(0, 0, pupilRad, 0, p.TWO_PI);
  ctx.fill();
  p.pop();

  let grad = ctx.createRadialGradient(400, 400, 200, 400, 400, 400);
  grad.addColorStop(0, "rgba(0,0,0,0.0)");
  grad.addColorStop(1, "rgba(0,0,0,0.85)");
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 800, 800);
};
